))
OR (
  "itemType" IN ('ngn_matrix', 'matrix')
  AND (
    COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'rows'), 0) = 0
    OR (
      length("correctAnswer") - length(replace("correctAnswer", '|||', ''))
    ) / 3 < COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'rows'), 0)
  )
)
OR (
  "itemType" IN ('ordered_response', 'drag_drop')
  AND COALESCE(
    "correctAnswer" = (
      SELECT string_agg(opt.value, ',' ORDER BY opt.ord)
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) WITH ORDINALITY AS opt(value, ord)
    ),
    false
  )
)
OR (
  "itemType" IN ('ngn_highlight', 'highlight')
  AND btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'text', '')) = ''
)
OR (
"itemType" IN ('case_study', 'unfolding_case', 'case_based')
AND (
  btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'caseGroupId', '')) = ''
  OR (
    SELECT COUNT(*)
    FROM "QuestionBankItem" AS case_group
    WHERE case_group.active = true
      AND case_group."fieldId" = "QuestionBankItem"."fieldId"
      AND case_group."itemType" = "QuestionBankItem"."itemType"
      AND left(btrim(case_group.options), 1) = '{'
      AND COALESCE(case_group.options::jsonb->>'caseGroupId', '')
        = COALESCE("QuestionBankItem".options::jsonb->>'caseGroupId', '')
  ) <> 6
))
OR NULLIF(curation_meta #>> '{itemQa,retiredReason}', '') IS NOT NULL
OR NULLIF(curation_meta #>> '{itemQa,retiredAt}', '') IS NOT NULL
OR "id" IN ('cmqwm3abk00081yqm9c46el5u', 'cmqwifwvc000a1yec5d73ooad', 'cmqwmxq3d000b1yq70s18zd8q', 'cmqwix0a200091y0ykmamr1la', 'cmqwm3a7u00071yqmb9apivma', 'cmqw4jsdz000k1y4r4ma76ptl', 'cmqw50659000o1yq20xebqqf6', 'cmqgswm9e001c1ytwdnxl3cat', 'cmqvzci9a000n1yttqt077oyp', 'cmqvos1ov000y1ylrqzi8i5rm', 'cmqgswl4o000y1ytwg8hrapx6', 'cmqvts9ow000f1yo8cwivxikq', 'cmqgswla700101ytwq3l8r6ql', 'cmqgswlj100131ytwck5mmrsy', 'cmr1bhbsu001s1yrm1z01p7kj', 'cmr1bhjhy003s1yrm7f8def3o', 'cmr7emvm000841y9twut54doz', 'cmr8sz5bk008v1y9nrfsd8vp3', 'cmr7jyeoa000q1yvujzxjzan4', 'cmr10qthh00431y8ay3g9yfji', 'cmr7iuyev004j1y66tupingmg', 'cmr8rp7ym00a71ye3b0hzviia', 'cmr13kwvr00401ygqrlcfo4lb', 'cmr1bhbzu001u1yrm6b40di5v', 'cmr1bhjll003t1yrmroht424m', 'cmqwv1fw700071ys23qek0zhv', 'cmqwwjfy000041y5kzp4bibjk', 'cmr0stdj4002u1yfnf1lsbw3o', 'cmr0wjqi9008g1ymh6c0xq7pt', 'cmr123ae3004c1y1umfhrmllu', 'cmr129aze00631y1uihv5f2ep', 'cmr76u8gw00sh1ywupke340yh', 'cmr8m20w200261yayojf5gkj5', 'cmr8r0v5g002d1ye38jnyif17', 'cmrm1lbmv001q1yga0n0esvbs', 'cmrm2a6x4008n1ygazw89g6f4', 'cmrm2a6zs008o1ygak5d8aihn', 'cmsewq90y005f1y566genullo', 'cmr77c94800yf1ywuyldkvn6o', 'cmr75yxbd00l91ywuik50psrb', 'cmr77c7ym00y11ywu08006add', 'cmr75n9t200gw1ywuk1f7os6e', 'cmr7647px00m31ywu6jjoeyxa', 'cmr8mns5w00ai1yay9swbo7zk', 'cmqwnohzh00091y7hex6gw5ip', 'cmqwrcmbq000m1yjh6ebdjbhm', 'cmr0tl18f005b1y8q3jhmtwou', 'cmr76uab300t41ywubu063xav', 'cmr7eseh700aa1y9tyoop9ziu', 'cmr8wawx600a71yab8te8iclv', 'cmr74yl7s009i1ywu0zm3gnna', 'cmr0yf0uq009d1ybsi1vz84vw', 'cmr76u9cr00ss1ywug0wsx63o', 'cmr8vlwgr005d1yabtg0hysms', 'cmqwx6mkq00031y2mmbh00wu5', 'cmr1bh65q000k1yrmatrq3wyt', 'cmr787yxj016h1ywu7vjk6z84', 'cmr8sz532008s1y9nglxbb5mm', 'cmroe7zyv000w1ybzode20s9g', 'cmrogf0we00591ymriqgrx4vt', 'cmsewieq700111y56bwiqzdqv', 'cmsewq8pv005b1y56ub57mswj', 'cmr1bh8es000z1yrm1u1j0eoq', 'cmr7echi000501y9tyfy2rm2q', 'cmr8nxmdj009u1yh664m9hz50', 'cmr8w3ln1008x1yabxco70mt6', 'cmr8utdfc00d01y0yx5mfuxk1', 'cmr0pyubm002t1y1g19jzu0s4', 'cmr0ylppz00ay1y