  AND (
    (question ~* 'daily dose' AND question ~* '(per dose|per administration|each dose)')
    OR (question ~* 'milligrams' AND question ~* 'milliliters' AND question ~* '\mand\M')
    OR question ~* 'volumes of'
  )
  AND "correctAnswer" !~ ';'
  AND "correctAnswer" !~* '\mand\M'
  AND "correctAnswer" !~ ','
)), false)
)
GROUP BY 1;

DO $guard$
BEGIN
  IF (
    SELECT count(*)
    FROM "QuestionBankItem" AS q
    JOIN livetest_plan AS p ON p.id = q.id
    WHERE q."fieldId" = p.field_id
      AND q.scenario IS NOT DISTINCT FROM p.expected_scenario
      AND q.question = p.expected_question
      AND q."correctAnswer" = p.expected_answer
      AND q.explanation = p.expected_explanation
      AND (
        (jsonb_typeof(q.options::jsonb) = 'array' AND q.options::jsonb = p.expected_options)
        OR q.options::jsonb->'options' = p.expected_options
      )
      AND q.active = true
      AND q."qaPassed" = true
  ) <> 57 THEN
    RAISE EXCEPTION 'a target row does not match the package current text';
  END IF;
  IF (
    SELECT count(*) FROM "QuestionBankItem"
    WHERE id = 'cmqgdi30k00251yr8p1il4n6l'
      AND active = true
      AND question = $livetest20261031$What is the most appropriate management?$livetest20261031$
      AND "correctAnswer" = $livetest20261031$Hold warfarin for 1 to 2 doses, recheck the INR in 24 to 48 hours, and resume at a lower weekly dose$livetest20261031$
  ) <> 1 THEN
    RAISE EXCEPTION 'rejected FNP Q4 no longer matches; apply nothing';
  END IF;
  IF (
    SELECT count(*) FROM "QuestionBankItem"
    WHERE id = 'cmqgmhhwq000d1ywqmjzx6zig'
      AND active = true
      AND question = $livetest20261031$What is the most likely explanation?$livetest20261031$
      AND "correctAnswer" = $livetest20261031$Recurrent viral URIs, typical for his age and daycare exposure$livetest20261031$
  ) <> 1 THEN
    RAISE EXCEPTION 'rejected FNP Q14 no longer matches; apply nothing';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM livetest_plan AS p
    JOIN "QuestionBankItem" AS q ON q."contentHash" = p.new_hash AND q.id <> p.id
    WHERE p.action = 'fix'
  ) THEN
    RAISE EXCEPTION 'a new contentHash collides with another row';
  END IF;
END
$guard$;

CREATE TABLE qbi_livetest_20261031_backup AS
SELECT q.*
FROM "QuestionBankItem" AS q
JOIN livetest_plan AS p ON p.id = q.id
WHERE q."fieldId" = p.field_id
  AND q.scenario IS NOT DISTINCT FROM p.expected_scenario
  AND q.question = p.expected_question
  AND q."correctAnswer" = p.expected_answer
  AND q.explanation = p.expected_explanation;

DO $guard$
BEGIN
  IF (SELECT count(*) FROM qbi_livetest_20261031_backup) <> 57 THEN
    RAISE EXCEPTION 'backup did not capture 57 rows';
  END IF;
  IF (SELECT count(DISTINCT id) FROM qbi_livetest_20261031_backup) <> 57 THEN
    RAISE EXCEPTION 'backup ids are not distinct';
  END IF;
END
$guard$;

WITH upd AS (
  UPDATE "QuestionBankItem" AS q
  SET
    scenario = p.new_scenario,
    question = p.new_question,
    "correctAnswer" = p.new_answer,
    explanation = p.new_explanation,
    options = (
      CASE
        WHEN jsonb_typeof(q.options::jsonb) = 'array' THEN p.new_options
        ELSE (
          (q.options::jsonb - 'distractorRationale' - 'clinicalReasoning' - 'keyTakeaways')
          || jsonb_build_object('options', p.new_options)
        )
      END
    )::text,
    "references" = p.new_refs,
    "generationMeta" = (
      COALESCE(q."generationMeta", '{}'::jsonb)
      - 'expertRationale'
      - 'expertRationaleVersion'
      - 'visualRationale'
      - 'rationaleEnrichedAt'
      - 'rationaleModel'
      - 'rationaleQualityScore'
      - 'rationaleEnrichFailCount'
      - 'rationaleEnrichFailReason'
    ) || jsonb_build_object('manualCorrection', true),
    "contentHash" = p.new_hash,
    manual_correction = true,
    "updatedAt" = NOW()
  FROM livetest_plan AS p
  WHERE q.id = p.id
    AND p.action = 'fix'
    AND q.id IN (SELECT id FROM qbi_livetest_20261031_backup)
    AND q.scenario IS NOT DISTINCT FROM p.expected_scenario
    AND q.question = p.expected_question
    AND q."correctAnswer" = p.expected_answer
    AND q.explanation = p.expected_explanation
  RETURNING q.id
)
SELECT count(*)::int AS content_fixes_updated FROM upd;

WITH upd AS (
  UPDATE "QuestionBankItem" AS q
  SET
    "correctAnswer" = p.new_answer,
    manual_correction = true,
    "updatedAt" = NOW()
  FROM livetest_plan AS p
  WHERE q.id = p.id
    AND p.action IN ('format', 'sibling')
    AND q.id IN (SELECT id FROM qbi_livetest_20261031_backup)
    AND q."correctAnswer" = p.expected_answer
    AND q.question = p.expected_question
    AND q.scenario IS NOT DISTINCT FROM p.expected_scenario
    AND q.explanation = p.expected_explanation
    AND position(';;' IN p.new_answer) > 0
    AND position(',' IN p.new_answer) = 0
  RETURNING q.id, p.action
)
SELECT
  count(*) FILTER (WHERE action = 'format')::int AS digoxin_format_updated,
  count(*) FILTER (WHERE action = 'sibling')::int AS sibling_format_updated
FROM upd;

WITH upd AS (
  UPDATE "QuestionBankItem" AS q
  SET
    active = false,
    manual_correction = true,
    "updatedAt" = NOW()
  FROM livetest_plan AS p
  WHERE q.id = p.id
    AND p.action = 'hide'
    AND q.id IN (SELECT id FROM qbi_livetest_20261031_backup)
    AND q.active = true
    AND q.question = p.expected_question
    AND q."correctAnswer" = p.expected_answer
    AND q.scenario IS NOT DISTINCT FROM p.expected_scenario
    AND q.explanation = p.expected_explanation
  RETURNING q.id
)
SELECT count(*)::int AS hidden FROM upd;

CREATE TEMP TABLE livetest_served_after ON COMMIT DROP AS
SELECT "fieldId", count(*)::int AS n
FROM "QuestionBankItem"
WHERE active = true
  AND "qaPassed" = true
  AND "fieldId" IN ('pance', 'nursing', 'pharmacy', 'aanp-fnp')
  AND (
  (
    COALESCE(curation_meta #>> '{studentEligibility,pipeline}', '') = 'student-eligibility-v1'
    AND COALESCE(curation_meta #>> '{studentEligibility,status}', '') = 'restored'
  )
  OR NOT COALESCE((
"itemType" IN ('select_all', 'sata') AND (
CASE
  WHEN position('|||' IN "correctAnswer") > 0 THEN
    1 + (length("correctAnswer") - length(replace("correctAnswer", '|||', ''))) / 3
  WHEN btrim(COALESCE("correctAnswer", '')) = '' THEN 0
  WHEN EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
    WHERE lower(btrim(opt.value)) = lower(btrim("correctAnswer"))
  ) THEN 1
  WHEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) >= 2
  AND (
    SELECT bool_and(EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
      WHERE lower(btrim(opt.value)) = lower(btrim(part))
    ))
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) THEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  )
  ELSE 1
END) < 2
OR (
  "itemType" IN ('vignette', 'mcq')
  AND (question ~* '\mselect all\M' OR COALESCE(scenario, '') ~* '\mselect all\M')
  AND (
CASE
  WHEN position('|||' IN "correctAnswer") > 0 THEN
    1 + (length("correctAnswer") - length(replace("correctAnswer", '|||', ''))) / 3
  WHEN btrim(COALESCE("correctAnswer", '')) = '' THEN 0
  WHEN EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
    WHERE lower(btrim(opt.value)) = lower(btrim("correctAnswer"))
  ) THEN 1
  WHEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) >= 2
  AND (
    SELECT bool_and(EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
      WHERE lower(btrim(opt.value)) = lower(btrim(part))
    ))
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) THEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  )
  ELSE 1
END) < 2
)
OR (
"itemType" IN ('ngn_bowtie', 'bow_tie')
AND (
  COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'actions'), 0) < 1
  OR COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'monitors'), 0) < 1
  OR (
    btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition', '')) <> ''
    AND (
      lower(regexp_replace(btrim((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition'), '\s+', ' ', 'g'))
        = lower(regexp_replace(btrim(question), '\s+', ' ', 'g'))
      OR (
        btrim(COALESCE(scenario, '')) <> ''
        AND lower(regexp_replace(btrim((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition'), '\s+', ' ', 'g'))
          = lower(regexp_replace(btrim(scenario), '\s+', ' ', 'g'))
      )
    )
  )
  OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(
      COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'actions', '[]'::jsonb)
      || COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'monitors', '[]'::jsonb)
      || CASE
           WHEN btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition', '')) <> ''
             THEN jsonb_build_array((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition')
           ELSE '[]'::jsonb
         END
    ) AS choice(value)
    WHERE length(btrim(choice.value)) >= 8
      AND position(lower(btrim(choice.value)) IN lower("correctAnswer")) > 0
      AND position('why other options are incorrect' IN lower(explanation)) > 0
      AND position(
        lower(btrim(choice.value)) IN split_part(lower(explanation), 'why other options are incorrect', 2)
      ) > 0
  )
))
OR (
  "itemType" IN ('ngn_matrix', 'matrix')
  AND (
    COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'rows'), 0) = 0
    OR (
      length("correctAnswer") - length(replace("correctAnswer", '|||', ''))
    ) / 3 < COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'rows'), 0)
  )
)
OR (
  "itemType" IN ('ordered_response', 'drag_drop')
  AND COALESCE(
    "correctAnswer" = (
      SELECT string_agg(opt.value, ',' ORDER BY opt.ord)
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) WITH ORDINALITY AS opt(value, ord)
    ),
    false
  )
)
OR (
  "itemType" IN ('ngn_highlight', 'highlight')
  AND btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'text', '')) = ''
)
OR (
"itemType" IN ('case_study', 'unfolding_case', 'case_based')
AND (
  btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'caseGroupId', '')) = ''
  OR (
    SELECT COUNT(*)
    FROM "QuestionBankItem" AS case_group
    WHERE case_group.active = true
      AND case_group."fieldId" = "QuestionBankItem"."fieldId"
      AND case_group."itemType" = "QuestionBankItem"."itemType"
      AND left(btrim(case_group.options), 1) = '{'
      AND COALESCE(case_group.options::jsonb->>'caseGroupId', '')
        = COALESCE("QuestionBankItem".options::jsonb->>'caseGroupId', '')
  ) <> 6
))
OR NULLIF(curation_meta #>> '{itemQa,retiredReason}', '') IS NOT NULL
OR NULLIF(curation_meta #>> '{itemQa,retiredAt}', '') IS NOT NULL
