SELECT 'before' AS phase, "fieldId", n FROM livetest_served_before
UNION ALL
SELECT 'after' AS phase, "fieldId", n FROM livetest_served_after
ORDER BY 1, 2;

DO $guard$
BEGIN
  IF (
    SELECT count(*)
    FROM "QuestionBankItem" AS q
    JOIN livetest_plan AS p ON p.id = q.id
    WHERE p.action = 'fix'
      AND q.scenario IS NOT DISTINCT FROM p.new_scenario
      AND q.question = p.new_question
      AND q."correctAnswer" = p.new_answer
      AND q.explanation = p.new_explanation
      AND (
        (jsonb_typeof(q.options::jsonb) = 'array' AND q.options::jsonb = p.new_options)
        OR q.options::jsonb->'options' = p.new_options
      )
      AND q."references" = p.new_refs
      AND q."contentHash" = p.new_hash
      AND q.manual_correction = true
      AND q.active = true
      AND q."qaPassed" = true
      AND COALESCE(q."generationMeta"->>'manualCorrection', '') = 'true'
      AND q.id IN (
        SELECT id FROM "QuestionBankItem"
        WHERE active = true AND "qaPassed" = true AND (
  (
    COALESCE(curation_meta #>> '{studentEligibility,pipeline}', '') = 'student-eligibility-v1'
    AND COALESCE(curation_meta #>> '{studentEligibility,status}', '') = 'restored'
  )
  OR NOT COALESCE((
"itemType" IN ('select_all', 'sata') AND (
CASE
  WHEN position('|||' IN "correctAnswer") > 0 THEN
    1 + (length("correctAnswer") - length(replace("correctAnswer", '|||', ''))) / 3
  WHEN btrim(COALESCE("correctAnswer", '')) = '' THEN 0
  WHEN EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
    WHERE lower(btrim(opt.value)) = lower(btrim("correctAnswer"))
  ) THEN 1
  WHEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) >= 2
  AND (
    SELECT bool_and(EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
      WHERE lower(btrim(opt.value)) = lower(btrim(part))
    ))
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) THEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  )
  ELSE 1
END) < 2
OR (
  "itemType" IN ('vignette', 'mcq')
  AND (question ~* '\mselect all\M' OR COALESCE(scenario, '') ~* '\mselect all\M')
  AND (
CASE
  WHEN position('|||' IN "correctAnswer") > 0 THEN
    1 + (length("correctAnswer") - length(replace("correctAnswer", '|||', ''))) / 3
  WHEN btrim(COALESCE("correctAnswer", '')) = '' THEN 0
  WHEN EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
    WHERE lower(btrim(opt.value)) = lower(btrim("correctAnswer"))
  ) THEN 1
  WHEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) >= 2
  AND (
    SELECT bool_and(EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
      WHERE lower(btrim(opt.value)) = lower(btrim(part))
    ))
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) THEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  )
  ELSE 1
END) < 2
)
OR (
"itemType" IN ('ngn_bowtie', 'bow_tie')
AND (
  COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'actions'), 0) < 1
  OR COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'monitors'), 0) < 1
  OR (
    btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition', '')) <> ''
    AND (
      lower(regexp_replace(btrim((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition'), '\s+', ' ', 'g'))
        = lower(regexp_replace(btrim(question), '\s+', ' ', 'g'))
      OR (
        btrim(COALESCE(scenario, '')) <> ''
        AND lower(regexp_replace(btrim((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition'), '\s+', ' ', 'g'))
          = lower(regexp_replace(btrim(scenario), '\s+', ' ', 'g'))
      )
    )
  )
  OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements_text(
      COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'actions', '[]'::jsonb)
      || COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'monitors', '[]'::jsonb)
      || CASE
           WHEN btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition', '')) <> ''
             THEN jsonb_build_array((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'condition')
           ELSE '[]'::jsonb
         END
    ) AS choice(value)
    WHERE length(btrim(choice.value)) >= 8
      AND position(lower(btrim(choice.value)) IN lower("correctAnswer")) > 0
      AND position('why other options are incorrect' IN lower(explanation)) > 0
      AND position(
        lower(btrim(choice.value)) IN split_part(lower(explanation), 'why other options are incorrect', 2)
      ) > 0
  )
))
OR (
  "itemType" IN ('ngn_matrix', 'matrix')
  AND (
    COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'rows'), 0) = 0
    OR (
      length("correctAnswer") - length(replace("correctAnswer", '|||', ''))
    ) / 3 < COALESCE(jsonb_array_length((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'rows'), 0)
  )
)
OR (
  "itemType" IN ('ordered_response', 'drag_drop')
  AND COALESCE(
    "correctAnswer" = (
      SELECT string_agg(opt.value, ',' ORDER BY opt.ord)
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) WITH ORDINALITY AS opt(value, ord)
    ),
    false
  )
)
OR (
  "itemType" IN ('ngn_highlight', 'highlight')
  AND btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'text', '')) = ''
)
OR (
"itemType" IN ('case_study', 'unfolding_case', 'case_based')
AND (
  btrim(COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->>'caseGroupId', '')) = ''
  OR (
    SELECT COUNT(*)
    FROM "QuestionBankItem" AS case_group
    WHERE case_group.active = true
      AND case_group."fieldId" = "QuestionBankItem"."fieldId"
      AND case_group."itemType" = "QuestionBankItem"."itemType"
      AND left(btrim(case_group.options), 1) = '{'
      AND COALESCE(case_group.options::jsonb->>'caseGroupId', '')
        = COALESCE("QuestionBankItem".options::jsonb->>'caseGroupId', '')
  ) <> 6
))
OR NULLIF(curation_meta #>> '{itemQa,retiredReason}', '') IS NOT NULL
OR NULLIF(curation_meta #>> '{itemQa,retiredAt}', '') IS NOT NULL
