    SELECT bool_and(EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text((
CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
      WHERE lower(btrim(opt.value)) = lower(btrim(part))
    ))
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  ) THEN (
    SELECT COUNT(*)
    FROM regexp_split_to_table("correctAnswer", ',') AS part
    WHERE btrim(part) <> ''
  )
  ELSE 1
END) < 2
