CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)
  ELSE COALESCE((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)->'options', '[]'::jsonb)
END)) AS opt(value)
      WHERE lower(btrim(opt.value)) = lower(btrim(part))
