CASE
  WHEN jsonb_typeof((
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
  ELSE '{}'::jsonb
END)) = 'array' THEN (
CASE
  WHEN left(btrim(options), 1) IN ('{', '[') THEN options::jsonb
